0,"Create a Go program that reads environment variables to configure an HTTP client, utilizing the standard library's `os` package for parsing the input. The program should set up the client with specific timeouts and proxy settings based on the provided variables, and then perform a GET request to a specified URL using the configured client. Finally, it should print the response body to the console.",807,,"['Here is a simple Go program that accomplishes what you described:

```go
package main

import (
	""fmt""
	""io/ioutil""
	""net/http""
	""net/url""
	""os""
	""time""
)

func main() {
	proxyUrl := os.Getenv(""PROXY_URL"")
	timeoutSeconds := os.Getenv(""TIMEOUT_SECONDS"")
	requestUrl := os.Getenv(""REQUEST_URL"")

	if proxyUrl == """" || timeoutSeconds == """" || requestUrl == """" {
		fmt.Println(""Please set the environment variables PROXY_URL, TIMEOUT_SECONDS and REQUEST_URL"")
		return
	}

	proxy, err := url.Parse(proxyUrl)
	if err != nil {
		fmt.Printf(""Invalid proxy URL: %s\n"", err)
		return
	}

	timeout, err := time.ParseDuration(timeoutSeconds + ""s"")
	if err != nil {
		fmt.Printf(""Invalid timeout: %s\n"", err)
		return
	}

	client := &http.Client{
		Transport: &http.Transport{Proxy: http.ProxyURL(proxy)},
		Timeout:   timeout,
	}

	resp, err := client.Get(requestUrl)
	if err != nil {
		fmt.Printf(""Failed to make GET request: %s\n"", err)
		return
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		fmt.Printf(""Failed to read response body: %s\n"", err)
		return
	}

	fmt.Println(string(body))
}
``` 

This program reads the `PROXY_URL`, `TIMEOUT_SECONDS` and `REQUEST_URL` environment variables to set up an HTTP client with specific timeouts and proxy settings. It then performs a GET request to the specified URL using this client, reads the response body, and prints it to the console.
