def update_username(email, password, new_username):
    # define login API endpoint and the required headers and body for login
    login_url = ""https://api.example.com/login""
    headers = {'Content-Type': 'application/json'}
    payload = {""email"": email, ""password"": password}

    # send POST request to log in 
    response = requests.post(login_url, data=json.dumps(payload), headers=headers)

    if response.status_code == 200:   # 200 means successful login
        token = response.json().get('token')

        # define user update API endpoint and the required headers and body for updating username
        update_url = ""https://api.example.com/update""
        headers['Authorization'] = 'Bearer ' + token  # add token to authorization header
        payload = {""username"": new_username}

        # send PUT request to update user details
        response = requests.put(update_url, data=json.dumps(payload), headers=headers)

        if response.status_code == 200:  # 200 means successful username update
            return {'success': True, 'data': response.json()}
        else:
            return {'success': False, 'error': ""Failed to update username.""}
    else:
        return {'success': False, 'error': ""Invalid email or password""}
``` 
Please replace `""https://api.example.com/login""` and `""https://api.example.com/update""` with actual API endpoints for your application. The response structure returned by the function is based on common practices in web APIs, you might need to adjust it according to the specifics of your API.
