import random
from datetime import datetime

class MessageEntity:
    def __init__(self):
        self.command_id = self._generate_unique_command_id()
        self.status_code, self.error_message = self._generate_random_result()
        self.timestamp = str(datetime.now())

    def _generate_unique_command_id(self):
        return random.randint(10000, 99999)

    def _generate_random_result(self):
        status_codes = [200, 400, 401, 403, 404, 500]
        error_messages = ['OK', 'Bad Request', 'Unauthorized', 'Forbidden', 'Not Found', 'Internal Server Error']
        random_index = random.randint(0, len(status_codes) - 1)
        return status_codes[random_index], error_messages[random_index]

def generate_message_entities(num):
    message_list = []

    for _ in range(num):
        message_list.append(MessageEntity())

    return message_list
