```python
def filter_even_length(strings):
    if not isinstance(strings, list):
        return ""Error: input should be a list""

    result = []

    for item in strings:
        if not isinstance(item, str):
            return f""Error: All items in the list should be string. {item} is not.""

        # Adding only strings with even lengths to the resulting list
        if len(item) % 2 == 0:
            result.append(item)

    return result
