import json, random, subprocess
from Crypto.Cipher import DES
from Crypto.Util.Padding import pad

def is_valid_json(data):
    try:
        data = json.loads(data)
        if ""access_token"" in data and ""expiry"" in data \
            and type(data[""access_token""]) == str and type(data[""expiry""]) == int\
                and len(str(data[""expiry""])) == 10 and data[""auth_type""].lower() == 'bearer':
                    return True
        else:
            print('Invalid JSON structure')
    except ValueError as e:
        print(e)
    return False

def encrypt(mode, key, message):
    if mode.upper() not in ['ECB', 'CBC']:  # Only CBC and ECB are supported by PyCryptodome
        raise Exception(""Unsupported DES cipher mode"")

    des = DES.new(key.encode(), DES.MODE_ECB) if mode.upper() == ""ECB"" else DES.new(key.encode(), DES.MODE_CBC)
    return des.encrypt(pad(message.encode(), DES.block_size)).hex()

def crossover(length, min_val, max_val, seed, json_string, mode, key):
    random.seed(seed)
    unique_random_sequence = set()

    while len(unique_random_sequence) < length:
        new_num = random.randint(min_val, max_val)
        if new_num not in unique_random_sequence:
            unique_random_sequence.add(new_num)

    is_json_validated = is_valid_json(json_string)

    if is_json_validated:
        encrypted_message = encrypt(mode, key, json_string)
        print(""Encrypted message:"", encrypted_message)

    return is_json_validated and bool(encrypted_message)
```
Please note that the DES encryption function here uses PyCryptodome library's DES cipher module. Make sure to install it using pip if not already installed before running this script: `pip install pycryptodome`. Also, please note that OpenSSL is required for the DES Cipher object creation.
