            if callable(info[""hash_function""]):
                available_crypto_functions.append({""name"": name, ""function"": info[""hash_function""]})

            elif callable(info[""cipher_function""]):
                available_crypto_functions.append({""name"": name, ""function"": info[""cipher_function""]})

