import json
from typing import Dict, Any, TypeVar, Callable

T = TypeVar('T')

class CryptoRegistry:
    _functions: Dict[str, T] = {}

    @classmethod
    def register_function(cls, function_id: str) -> Callable[[Dict[str, Any]], T]:
        def decorator(function: Callable[..., Any]) -> T:
            cls._functions[function_id] = function
            return function

        return decorator

    @classmethod
    def create_instance(cls, function_id: str) -> T:
        if function_id in cls._functions:
            return cls._functions[function_id]()

        return None

    @classmethod
    def convert_to_json(cls) -> str:
        registry_dict = {k: v.__name__ for k, v in cls._functions.items()}

