import os
import fs

def read_file_synchronously(directory_path):
    if not os.path.isdir(directory_path):
        raise ValueError(""Directory does not exist"")

    file_path = os.path.join(directory_path, 'example.txt')

    try:
        with fs.open_fs(file_path) as dir_fs, \
             dir_fs.open('example.txt', 'rt') as text_file:
            return text_file.read()

    except (FileNotFoundError, IOError):
        raise ValueError(""Error reading file"")

def filter_even_length_strings(input_list):
    if not all(isinstance(i, str) for i in input_list):
        raise TypeError('All elements of the list must be strings')

    return [x for x in input_list if len(x) % 2 == 0]

def main():
    directory_path = ""/path/to/directory""

    try:
        file_content = read_file_synchronously(directory_path)

        print(""File content:"", file_content)

        strings_list = [""example"", ""test"", ""python""]
        filtered_strings = filter_even_length_strings(strings_list)

        print(""Filtered list:"", filtered_strings)

    except ValueError as e:
        print(""Value Error:"", str(e))

    except TypeError as e:
        print(""Type Error:"", str(e))

if __name__ == ""__main__"":
    main()
```

