        self.scores = []

    def createRandomString(self, length):
        return ''.join([random.choice(string.ascii_letters + string.digits) for _ in range(length)])

    def verifyUniqueness(self, playerId, gameMode, scores):
        if any(score.playerId == playerId and score.gameMode == gameMode for score in scores):
            raise Exception('Player ID and Game Mode pair is not unique')

    def createGameScores(self, numberOfGames):
        if numberOfGames < 0:
            raise ValueError(""numberOfGames must be non-negative"")

        self.scores = []
        for _ in range(numberOfGames):
            playerId = self.createRandomString(random.randint(1, self.maxPlayerIdLength))
            gameMode = self.createRandomString(random.randint(1, self.maxGameModeLength))

            self.verifyUniqueness(playerId, gameMode, self.scores)

            winProbability = self.randomizeWinProbability()
            difficulty = random.choice(['easy', 'medium', 'hard'])
            score = GameScore(playerId=playerId, gameMode=gameMode, difficulty=difficulty, winProbability=winProbability)

            self.scores.append(score)
        return self.scores

    def randomizeWinProbability(self):
        # Example of a rule based probability: The higher the game mode length, the higher the win probability
        avg_gameModeLength = sum([len(score.gameMode) for score in self.scores]) / len(self.scores) if self.scores else 1

        return avg_gameModeLength / self.maxGameModeLength

    def verifyUniquenessInScores(self, scores):
        # Check all unique combinations of playerId and gameMode across all scores in the array
        for i in range(len(scores)):
            for j in range(i+1, len(scores)):
                if scores[i].playerId == scores[j].playerId and scores[i].gameMode == scores[j].gameMode:
                    raise Exception('Player ID and Game Mode pair is not unique across the given scores')
        return True
``` 
