import hashlib
import requests
import json

def fetch_and_update_data(initial_pairs: dict)  -> dict:
    updated_dict = initial_pairs.copy()
    while True:
        user_input = input(""Enter new key-value pair or 'done' to finish: "")
        if user_input.lower() == 'done':
            break

        try:
            key, value = user_input.split('=', 1)
            updated_dict[key] = value
        except ValueError:
            print(""Invalid input format. Please enter a key-value pair."")

    while True:
        user_input = input(""Enter an existing key for removal or 'done' to finish: "")
