class ECommerceApp:
    def __init__(self, max_instances=10):
        self.max_instances = max_instances
        self.processing_modules = []  # A list to store all order processing instances

    def create_instance(self):
        if len(self.processing_modules) < self.max_instances:
            self.processing_modules.append(OrderProcessing())
        else:
            raise Exception(""Maximum number of instances reached"")

    def get_instance(self, index):
