import hashlib
import struct
from array import array

class EnhancedHashAndCrc:
    def __init__(self, file_path, n, rx_tag=None, rnti=None):
        self.file_path = file_path
        self.n = self.validate_input(n)
        self.rx_tag = rx_tag if rx_tag else 0x0000FFFF
        self.rnti = rnti if rnti else 0xFFFFFFFF
        self.memory_pool = []

    def validate_input(self, n):
        if not isinstance(n, int) or not (1 <= n <= 100):
            raise ValueError(""Input must be an integer between 1 and 100."")
        return n

    def calculate_md5(self, file_content):
        hash_object = hashlib.md5()
        hash_object.update(file_content)
        return hash_object.hexdigest()

    def calculate_crc(self, data):
        crc = 0xFFFFFFFF

        for _ in range(8 * len(data)):
            crc ^= data[(_ >> 3) & 7]
            if (crc & 1) == 1:
