import socket
import hashlib
from tqdm import tqdm

def resolve_hostname(ip):
    try:
        return socket.gethostbyaddr(ip)[0]
    except (socket.herror, socket.gaierror):
        pass

def md5_hash_file(filename):
    hash_md5 = hashlib.md5()

    with open(filename, ""rb"") as f:
        # Read and update hash in chunks
        for byte_block in iter(lambda: f.read(4096), b""""):
            hash_md5.update(byte_block)

    return hash_md5.hexdigest()

def main():
    ip_list = [""172.217.163.14"", ""8.8.8.8""]  # example IPs

    for ip in ip_list:
        hostname = resolve_hostname(ip)
        if hostname is not None:
            print(""First successfully resolved hostname: "", hostname)
            break

    filepath = ""yourfile.txt""  # replace with your file path
    print(""MD5 hash of the file: "", md5_hash_file(filepath))

if __name__ == '__main__':
    main()
