from hashlib import md5

def resolve_hostname(ip_addresses):
    for ip in ip_addresses:
        try:
            return socket.gethostbyaddr(ip)[0]
        except socket.herror:
            continue
    return None

def calculate_md5_hash_with_dns_resolution(filepath, ip_addresses=['192.168.1.1', '8.8.8.8', '93.184.216.34']):
    hostname = resolve_hostname(ip_addresses)
