class Account:
    def __init__(self, account_number, balance, account_type):
        self.account_number = account_number
        self.balance = balance
        self.account_type = account_type

    def deposit(self, amount):
        self.balance += amount
        logger.info(f""Deposited {amount} into account number {self.account_number}, new balance: {self.balance}"")

    def withdraw(self, amount):
        if amount <= self.balance: 
            self.balance -= amount
            logger.info(f""Withdrew {amount} from account number {self.account_number}, new balance: {self.balance}"")
        else: 
            print(""Insufficient funds."")

    def check_balance(self):
        return self.balance

class BankBranch:
    def __init__(self, branch_id, initial_accounts=10):
        self.branch_id = branch_id
        self.accounts = {f""{i}"": Account(f""{i}"", 500, ""Savings"") for i in range(initial_accounts)}

    def deposit_money(self, account_number, amount):
        if account_number in self.accounts:
            self.accounts[account_number].deposit(amount)
        else: 
            print(""Invalid Account Number"")

    def withdraw_money(self, account_number, amount):
        if account_number in self.accounts:
            self.accounts[account_number].withdraw(amount)
        else: 
            print(""Invalid Account Number"")

# Testing        
bank = BankBranch('1')
t1 = threading.Thread(target=bank.deposit_money, args=(""5"", 300))
t2 = threading.Thread(target=bank.withdraw_money, args=(""5"", 200))
t1.start()
t2.start()
```
