            if number % 1 != 0:
                floatingPoints.append(number)
        except ValueError as e:
            errors.append(""Token '{}' does not represent a valid number"".format(token))

    if len(errors) > 0:
        print('Errors encountered during extraction:')
        for error in errors:
            print(error)

    if len(floatingPoints) == 0:
        print(""No even float found"")
    else:
        smallest_float = min(floatingPoints)
        print(""Smallest floating-point number is {}"".format(smallest_float))

        if smallest_float % 2 == 0:
            print('The smallest floating-point number was even')
        else:
            print('The smallest floating-point number was not even')
```
