import os
import sys

def read_file_synchronously(directory_path):
    if not os.path.exists(directory_path):
        raise FileNotFoundError(""Directory does not exist."")

    file_path = os.path.join(directory_path, 'example.txt')

    if not os.path.isfile(file_path):
        raise FileNotFoundError(""File 'example.txt' does not exist in the directory."")

    try:
        with open(file_path, 'r') as file:
            return file.read()
    except IOError as e:
        raise IOError(f""Error reading file: {e}"")

def filter_even_length_strings(input_list):
    if not all(isinstance(item, str) for item in input_list):
        raise ValueError(""All elements in the input list must be strings."")

    return [item for item in input_list if len(item) % 2 == 0]

def main():
    try:
        directory_path = ""/path/to/directory""

        content = read_file_synchronously(directory_path)

        filtered_content = filter_even_length_strings(content.splitlines())

        print(filtered_content)

    except Exception as e:
        print(f""An error occurred: {e}"", file=sys.stderr)

if __name__ == ""__main__"":
    main()
