import math

def nth_fib(n):
    if n <= 0:
        print(""Invalid input"")
        return None
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        a, b = 0, 1
        for i in range(3, n + 1):
            a, b = b, a + b
        return b

def fib_sequence(n):
    if n <= 0:
        print(""Invalid input"")
        return None
    sequence = [nth_fib(i) for i in range(1, n + 1)]
    return sequence

def perfect_square(num):
    root = math.isqrt(num)
    return root * root == num

def main():
    while True:
        try:
            user_input = input(""Enter the number of terms in the Fibonacci sequence (or 'exit' to quit): "")
            if user_input.lower() == 'exit':
                break

            n = int(user_input)
            sequence = fib_sequence(n)
            print(f""Fibonacci Sequence: {sequence}"")

            perfect_squares = [num for num in sequence if perfect_square(num)]
            if perfect_squares:
                print(""Perfect squares in the Fibonacci sequence:"", perfect_squares)
        except ValueError:
            print(""Invalid input. Please enter a positive integer."")

main()
