def output_to_file(filename, data):
    try:
        with open(filename, 'w') as f:
            f.write(str(data))
    except Exception as e:
        print(""Failed to write to file. Reason: "" + str(e))
        sys.exit()

def main():
    try:
        opts, args = getopt.getopt(sys.argv[1:], 'hs:o:', ['help', 'sum=', 'output='])
    except getopt.GetoptError as err:
        print(""Invalid argument or missing argument value."")
        usage()
        sys.exit(2)

    sum_file = None
    output_file = None
    data = 0

    for opt, arg in opts:
        if opt in ('-h', '--help'):
            usage()
            sys.exit()
        elif opt in ('-s', '--sum'):
            sum_file = arg
            data = calculate_sum(sum_file)
        elif opt in ('-o', '--output'):
            output_file = arg
    if not sum_file:
        print(""Sum file is required for option -s."")
        usage()
        sys.exit()

    if output_file:
        output_to_file(output_file, data)
    else:
        with redirect_stdout(open(os.devnull, 'w')):  # Suppress print output for -s option
            print(data)

if __name__ == ""__main__"":
    main()
